<script setup>
import { computed, ref, watch } from 'vue'
import { get, post, put, patch, perform } from '../api'
import { today } from '../utils'
const props=defineProps({resource:{type:String,required:true}}),rows=ref([]),loading=ref(false),saving=ref(false),dialog=ref(false),form=ref({}),error=ref('')
const configs={users:{title:'人员账户',url:'/admin/users',cols:[['username','账号'],['display_name','姓名'],['role','角色'],['enabled','启用']],newUrl:'/admin/users'},departments:{title:'科室管理',url:'/admin/departments',cols:[['name','科室'],['location','位置'],['enabled','启用']],newUrl:'/admin/departments'},doctors:{title:'医生管理',url:'/admin/doctors',cols:[['name','姓名'],['department_name','科室'],['title','职称'],['specialty','擅长方向']],newUrl:'/admin/doctors'},schedules:{title:'排班号源',url:'/admin/schedules',cols:[['work_date','日期'],['period','时段'],['doctor_name','医生'],['total','号源'],['remaining','余号'],['status','状态']],newUrl:'/admin/schedules'},drugs:{title:'药品目录',url:'/admin/drugs',cols:[['code','编码'],['name','药品'],['price','价格'],['stock','库存'],['reserved','预占']],newUrl:'/admin/drugs'},logs:{title:'操作审计',url:'/admin/logs',cols:[['created_at','时间'],['actor_name','操作者'],['operation','操作'],['success','结果']],newUrl:null}}
const config=computed(()=>configs[props.resource] || {title:'管理',url:'/admin/users',cols:[],newUrl:null})
let loadVersion = 0
async function load(){const version=++loadVersion;loading.value=true;error.value='';try{const params={size:100};if(props.resource==='schedules')params.from=today();const data=await get(config.value.url,params);if(version===loadVersion)rows.value=data}catch(e){if(version===loadVersion)error.value=e.message}finally{if(version===loadVersion)loading.value=false}}
function newSchedule(){const [year,month,day]=today().split('-').map(Number),next=new Date(Date.UTC(year,month-1,day+1)),date=`${next.getUTCFullYear()}-${String(next.getUTCMonth()+1).padStart(2,'0')}-${String(next.getUTCDate()).padStart(2,'0')}`;return {doctor_id:'',work_date:date,period:'AM',start_time:`${date}T08:00:00`,end_time:`${date}T12:00:00`,total:30,fee:20,status:'OPEN'}}
function open(row){form.value=row?{...row}:props.resource==='users'?{username:'',password:'Demo12345!',display_name:'',role:'PATIENT',enabled:true}:props.resource==='departments'?{name:'',location:'',description:'',enabled:true}:props.resource==='doctors'?{user_id:'',department_id:'',title:'',specialty:'',enabled:true}:props.resource==='schedules'?newSchedule():props.resource==='drugs'?{code:'',name:'',spec:'',unit:'盒',price:0,threshold:10,enabled:true}:{};dialog.value=true}
async function save(){
  if(saving.value)return
  const c=config.value,id=form.value.id
  const update=props.resource==='users'?patch:put
  const action=()=>id?update(`${c.url}/${id}`,form.value):post(c.newUrl,form.value)
  saving.value=true
  try{await perform(action,async()=>{dialog.value=false;await load()},'保存成功')}finally{saving.value=false}
}
watch(()=>props.resource,()=>{rows.value=[];dialog.value=false;load()},{immediate:true})
</script>
<template><div><div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>{{ config.title }}</h1><p>管理员维护基础资料，已发生业务的数据采用停用和历史留存。</p></div><div class="action-row"><el-button @click="load">刷新</el-button><el-button v-if="config.newUrl" type="primary" @click="open(null)">新增</el-button></div></div><el-alert v-if="error" :title="error" type="error"/><section class="panel"><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="c in config.cols" :key="c[0]" :prop="c[0]" :label="c[1]" min-width="120"/><el-table-column v-if="config.newUrl && resource!=='logs'" label="操作" width="90"><template #default="s"><el-button size="small" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" :title="form.id?'编辑':'新增'" width="560px"><el-form label-width="90px"><template v-if="resource==='users'"><el-form-item label="账号"><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.display_name" :disabled="!!form.id"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" :disabled="!!form.id"><el-option v-for="r in ['PATIENT','DOCTOR','CASHIER','PHARMACIST','ADMIN']" :key="r" :label="r" :value="r"/></el-select></el-form-item><el-form-item :label="form.id ? '重置密码' : '密码'"><el-input v-model="form.password" show-password :placeholder="form.id ? '留空则不修改密码' : '至少 8 位'"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></template><template v-else-if="resource==='departments'"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item></template><template v-else-if="resource==='doctors'"><el-form-item label="账户 ID"><el-input-number v-model="form.user_id" :min="1"/></el-form-item><el-form-item label="科室 ID"><el-input-number v-model="form.department_id" :min="1"/></el-form-item><el-form-item label="职称"><el-input v-model="form.title"/></el-form-item><el-form-item label="擅长方向"><el-input v-model="form.specialty"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></template><template v-else-if="resource==='schedules'"><el-form-item label="医生 ID"><el-input-number v-model="form.doctor_id" :min="1"/></el-form-item><el-form-item label="日期"><el-date-picker v-model="form.work_date" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="时段"><el-input v-model="form.period" placeholder="AM / PM"/></el-form-item><el-form-item label="开始时间"><el-input v-model="form.start_time" placeholder="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-input v-model="form.end_time" placeholder="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="号源"><el-input-number v-model="form.total" :min="1"/></el-form-item><el-form-item label="挂号费"><el-input-number v-model="form.fee" :min="0" :precision="2"/></el-form-item></template><template v-else-if="resource==='drugs'"><el-form-item label="编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="规格"><el-input v-model="form.spec"/></el-form-item><el-form-item label="价格"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item><el-form-item label="预警阈值"><el-input-number v-model="form.threshold" :min="0"/></el-form-item></template><p v-else class="muted">该管理项请使用完整字段接口维护；此页提供已保存数据查询。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save" :loading="saving" :disabled="!config.newUrl">保存</el-button></template></el-dialog></div></template>
